// План specs/technicians-sms.md 3.1 (кейс #8595f7). PROD, admin, компания «test», десктоп 1440, EN. @prod-safe: Send НЕ нажимается
// (кнопка неактивна), SMS не отправляется; перехват message-technicians/send-sms стоит как страховка (expectNothingSent(…, 0) не используется —
// проверяем, что POST вообще не было). Отмечается только «QA-Tech Gamma» (без согласия на SMS).
// Источник: «מה רצוי» — 1) когда ни у одного выбранного техника нет согласия/телефона, рядом с Send показано объяснение; 2) счётчик считает то,
// что написал пользователь, или объясняет, что включена фиксированная добавка. Факты 17.11: причина блокировки над Send,
// счётчик 0/1562 + «+38 characters Techory adds: the sender and the opt-out line».
// Тексты HE не проверяются (решение 18.10: непереведённые/HE-тексты не требование).
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, L, TECHS, interceptSending, openTechnicians, textSelectedButton } from './technicians-sms-helpers';

test.use({ storageState: ADMIN_STATE, serviceWorkers: 'block', viewport: { width: 1440, height: 900 } });

test.describe('Text a technician — why Send is disabled and the character counter (#8595f7)', () => {
  test('Only a technician without SMS consent selected: reason shown above Send, Send disabled; counter "0 / 1562" + "+38 characters" note, counts typed text #8595f7 @desktop @prod-safe', async ({ page, context }) => {
    const guard = await interceptSending(context);
    await openTechnicians(page, 'en');
    const cb = page.getByRole('row').filter({ hasText: TECHS.skipped }).first().getByRole('checkbox').first();
    await cb.click();
    await expect(cb).toBeChecked();
    await textSelectedButton(page, 'en').click();

    const dialog = page.getByRole('dialog');
    await expect(dialog).toBeVisible();
    const send = dialog.getByRole('button', { name: L.en.send });
    await expect(send).toBeDisabled();
    // Причина блокировки (источник: «מה רצוי» п.1) — над Send, с указанием, что добавить
    await expect(dialog.getByText(/can't get texts.*phone number.*SMS consent/s)).toBeVisible();
    await expect(dialog.getByText(/won't be texted/)).toBeVisible();

    // Счётчик (источник: «מה רצוי» п.2)
    await expect(dialog.getByText('0 / 1562', { exact: true })).toBeVisible();
    await expect(dialog.getByText(/\+38 characters Techory adds/)).toBeVisible();
    await dialog.locator('#technician-message').fill('hello');
    await expect(dialog.getByText('5 / 1562', { exact: true })).toBeVisible();
    await expect(send, 'Send остаётся неактивной, пока никому нельзя отправить').toBeDisabled();

    expect(guard.posts, 'POST message-technicians не было').toBe(0);
    expect(guard.blocked, 'send-sms / assignment-notices не вызывались').toBe(0);
  });
});
